export function districtDemoState(){const s=migrateState(echoEventDemo()),d=s.districts;d.demo=true;s.frontier.echoDemo=false;s.frontier.demo=true;s.region='valley';s.player.x=370;s.player.y=395;s.stats.harvested=Math.max(2,s.stats.harvested);s.stats.sold=Math.max(1,s.stats.sold);s.colony.nextHordeDay=s.day+5;s.supply.plans={};s.money=360;for(const id of ids){d.unlocked[id]=true;d.stores[id]={wood:12,stone:6,scrap:10,parts:5,bread:6,cloth:4,herb:4,bean:4};}Object.assign(s.inventory,{seedBean:8,seedCorn:8,seedCotton:6,seedHerb:4,potato:4,stew:2,medkit:2,fieldSample:1});Object.assign(d.stores.stationMarket,{jam:4,stew:2,seedBean:4});Object.assign(d.stores.railDepot,{circuit:2,cotton:6,ammo:20});for(let i=0;i<4;i++)Object.assign(d.plots[i],{crop:'bean',growth:CROPS.bean.grow,wateredDay:s.day});d.track='watergate';return s;}
