 districtCostPlan(cost,region=this.s.region){const plan={};for(const [id,n]of Object.entries(cost||{})){if(!ITEMS[id]||!Number.isInteger(n)||n<0||this.districtAvailable(id,region)<n)return null;let left=n;for(const key of CROPS[id]?[id,'hardy_'+id,'fine_'+id]:[id]){const amount=Math.min(left,(this.s.inventory[key]||0)+(this.districtStore(region)?.[key]||0)-(plan[key]||0));if(amount>0){plan[key]=(plan[key]||0)+amount;left-=amount;}}if(left>0)return null;}return plan;}
