 setDistrictReserve(id,n){if(!this.d.reserves[this.s.region]||!GOODS.includes(id)||!Number.isInteger(n)||n<0||n>99)return false;this.d.reserves[this.s.region][id]=n;return true;}
 districtUnlockReason(id){const def=DISTRICTS[id];if(!def)return '未知地区';if(this.d.unlocked[id])return '';const gates={valley:[this.s.stats.harvested>=1,'完成首次收获'],stationMarket:[this.s.stats.sold>=1,'完成首次出售'],courtyard:[!!this.resident('farmer'),'救出阿禾'],quarantine:[this.r.outposts.hospital>=2,'恢复医院前哨'],railDepot:[!!this.resident('mechanic')&&this.r.tech.power,'救出陈工并完成动力研究']};return gates[id][0]?'':gates[id][1];}
 unlockDistrict(id){const def=DISTRICTS[id];if(!def||this.d.unlocked[id])return false;const reason=this.districtUnlockReason(id);if(reason||this.s.region!==def.parent||distance(this.s.player,def.gate)>115){this.toast(reason||'请到'+REGIONS[def.parent].name+'的入口旁修复通路。','warn');return false;}if(!this.districtPay(def.cost,def.parent)){this.toast('修复入口需要：'+this.bundleText(def.cost)+'。携带材料前往入口。','warn');return false;}this.d.unlocked[id]=true;this.d.track=POINTS.find(p=>p.region===id).id;this.districtLog(id,'新地区入口已开通');this.toast(def.name+'已开放 · 返回世界地图即可前往','gold');this.assignRegion();return true;}
 districtTravelReason(id){if(!REGIONS[id])return '未知地区';if(DISTRICTS[id]&&!this.d.unlocked[id])return this.districtUnlockReason(id)||'先到'+REGIONS[DISTRICTS[id].parent].name+'修复入口';if(['warning','active'].includes(this.s.horde.phase)&&id!=='farm'&&id!==this.s.region)return '家园尸潮预警或进攻中，请先准备守家';if(this.d.battle&&id!==this.s.region)return '挑战中：使用撤退按钮结束本次挑战，建设与研究保留';if(this.f.route&&DISTRICTS[id])return '先结束三站远征，再进入相邻地区';return '';}
 travel(id){const reason=this.districtTravelReason(id);if(reason){this.toast(reason,'warn');return false;}const old=this.s.region;this._districtTravelDiscount=(id==='courtyard'||old==='courtyard')&&this.flag('routes','roof')?8:(id==='quarantine'||old==='quarantine')&&this.flag('corridor','vent')?5:0;const ok=super.travel(id);this._districtTravelDiscount=0;if(ok&&old!==id&&DISTRICTS[id]){this.d.focus=id;this.districtLog(id,'抵达地区');}return ok;}
