 districtAct(id,key,n=1){const q=this.districtQuote(id,key,n);if(q.reason){this.toast(q.reason,'warn');return false;}if(!this.districtPay(q.cost,q.region))return false;q.cost=copy(this._districtPaid);this.s.money-=q.fee;const p=this.ensurePoint(id);p.days[q.sharedDaily?'all':key]=this.s.day;if(q.bed!=null)p.days['bed'+q.bed]=this.s.day;
 if(q.effect?.startsWith('specialist:'))this.assignDistrictWorker(q.effect.split(':')[1],'courtyard');if(q.worker)this.assignDistrictWorker(q.worker,q.region);
 if(q.minutes){let minutes=q.minutes;if(q.point==='ward'&&this.point('medservice').choice==='care')minutes*=.75;if(q.point==='sterile'&&this.point('medservice').choice==='kit')minutes*=.8;const job={id:'district-job-'+this.d.serial++,point:id,key,region:q.region,cost:copy(q.cost),out:copy(q.out),money:q.money,effect:q.effect,total:minutes,remaining:minutes,paused:false,power:q.power||null,worker:q.worker||null,bed:q.bed??null,label:q.label};this.d.jobs.push(job);this.districtLog(q.region,q.label+' · 已投料，关闭菜单后推进');this.toast('已开始：'+q.label+' · '+Math.ceil(minutes)+'游戏分钟');}
 else this.completeDistrictAction({...q,label:q.label});this.assignRegion();this.emit('quest');return true;
 }
 completeDistrictAction(q){const p=this.ensurePoint(q.point),effect=q.effect||'',args=effect.split(':'),id=q.point;this.districtPut(q.region,q.out);this.s.money+=q.money||0;p.count++;if(q.money)this.s.stats.sold+=Math.max(1,Object.values(q.cost||{}).reduce((a,b)=>a+b,0));
 if(args[0]==='flag')p.flags[args[1]]=true;
 if(args[0]==='choice')p.choice=args[1];
 if(args[0]==='plant')this.plantValley(args[1],args[2]);
 if(effect==='herbclip')p.readyDay=this.s.day+1;
 if(effect==='herbuproot'){p.flags.built=false;p.readyDay=0;}
 if(args[0]==='farmwork'){p.choice=args[1];this.assignDistrictWorker('farmer','valley');}
 if(args[0]==='recall')this.assignDistrictWorker(args[1],null);
 if(args[0]==='agri'){p.choice=args[1];p.readyDay=this.s.day+1;}
 if(args[0]==='closeShop')delete p.flags[args[1]];
 if(effect==='customer'){p.flags.customers=(p.flags.customers||0)+1;this.addReputation(2);}
 if(effect==='inspect'){p.flags.inspected=this.s.day;this.toast(this.s.day%2?'检查结果：外壳破损，需要废金属2；修复售28金。':'检查结果：轴承磨损，需要零件1；修复售38金。');}
 if(effect==='restoreDone')p.flags.inspected=0;
 if(args[0]==='assistant'){for(const [k,r]of Object.entries(this.d.workers))if(r==='stationMarket')this.assignDistrictWorker(k,null);p.choice=args[1];p.flags.price??='normal';this.assignDistrictWorker(args[1],'stationMarket');}
 if(args[0]==='price')p.flags.price=args[1];
 if(effect==='recallshop')for(const [k,r]of Object.entries({...this.d.workers}))if(r==='stationMarket')this.assignDistrictWorker(k,null);
 if(args[0]==='noise'){this.d.noise={x:args[1]==='west'?530:1130,y:405,t:12,region:'courtyard'};this.emit('closeMenu');}
 if(effect==='house')p.flags.built=true;
 if(effect==='dismantlehouse')p.flags.dismantled=true;
 if(effect==='rest'&&this.s.region===q.region){this.s.player.hp=Math.min(this.maxHp(),this.s.player.hp+25);this.s.player.stamina=this.maxSta();}
 if(args[0]==='neighbor')p.flags[args[1]]=(p.flags[args[1]]||0)+1;
 if(args[0]==='specialist'||args[0]==='specialistTool'){p.flags[args[1]]=true;const reward={farmer:{seedHerb:2},medic:{medkit:1},mechanic:{parts:2}}[args[1]];this.toast('支路开放：前往南侧新出现的探索点领取物资。','gold');if(args[0]==='specialist'&&this.d.workers[args[1]]==='courtyard')this.assignDistrictWorker(args[1],null);}
 if(effect==='scout'){p.readyDay=this.s.day+2;this.toast('侦察报告：地图标出所有活跃敌人，未来两天本区敌人感知降低。','gold');}
 if(args[0]==='power'){const a=this.d.power[args[1]],i=a.indexOf(args[2]);if(i<0)a.push(args[2]);else a.splice(i,1);}
 if(effect==='corridor')p.flags.pass=true;
 if(effect==='vent'){p.flags.vent=p.flags.pass=true;}
 if(args[0]==='experiment')p.flags[args[1]]=true;
 if(args[0]==='ward'){p.flags.recovered=(p.flags.recovered||0)+1;this.addReputation(3);this.districtLog(q.region,['康复者：曾经封闭的街道又有了炊烟。','康复者：下次会把修理工具带回营地。'][Number(args[1])]);}
 if(args[0]==='evidence'){if(args[1]==='water'){p.flags.solved=true;this.districtPut(q.region,{parts:2,fieldSample:1});this.toast('证据吻合：旧支管回流。医疗专营与净化处理路线已开放。','gold');}else{this.toast('通风样本较干净，管线图显示旧支管回流。重新对照水质证据。','warn');}}
 if(args[0]==='battle')this.startDistrictBattle(args[1]);
 if(effect==='normal'&&this.d.battle?.id==='overload')this.finishDistrictBattle(false);
 if(effect==='dismantlemachine'){p.flags.salvaged=true;p.flags.wire=p.flags.gear=false;}
 if(args[0]==='removeModule')delete p.flags[args[1]];
 if(id==='wetland'&&this.flag('wetland','built'))for(const plot of this.d.plots.filter(p=>p.bed===1).slice(-2))plot.buffer=true;
 if(Object.keys(q.out||{}).length)this.recordProduced(q.out);this.districtLog(q.region,q.label+'完成'+(Object.keys(q.out||{}).length?' · 成品存入本地仓库':''),q.out||{},(q.money||0)-(q.fee||0));this.toast(q.label+'完成'+(Object.keys(q.out||{}).length?' · '+this.bundleText(q.out)+'已入本地仓库':''),'gold');
 }
